    // ========== The same metrics, per DESIGN ==========
    // Emmentaler is optically sized: emmentaler-11 is not emmentaler-20 shrunk, it is
    // a different drawing with different metrics. LilyPond therefore does not scale one
    // table — it picks the FILE whose design size is closest by ratio to the size asked
    // for (lily/font-select.cc:41-70 best_rounded_design_size, ported as
    // EmmentalerDesignSize) and reads that file's metrics, then scales them.
    //
    // Each table below is in ITS OWN design's staff spaces, exactly as the flat
    // constants above are in the 20's. A grob's box on the page is
    //     designTable[chosen].Glyph * magstep(font-size)
    // — LilyPond's own requested/actual magnification cancels against the design size
    // (lily/font-select.cc:185 find_scaled_font with lily/modified-font-metric.cc:62-68
    // Modified_font_metric::get_indexed_char_dimensions), which is why
    // the multiplication a caller already does does not change; only the table does.

    /// <summary>
    /// Every font-derived metric of ONE Emmentaler design, in that design's own staff
    /// spaces.
    /// </summary>
    /// <remarks>
    /// LILYPOND-REF: lily/open-type-font.cc:390-408 get_indexed_char_dimensions — one
    ///   loaded font file answers for one design; LilyPond holds as many as the score
    ///   asks for.
    /// ⚠️ These are NOT page staff spaces. Scale by the grob's magstep before use.
    /// </remarks>
    internal sealed class DesignMetrics
    {
        /// <summary>The rounded size in the file name (emmentaler-11.otf is 11).</summary>
        public int Rounded { get; init; }

        /// <summary>The design size the file really carries — 11.22 for the 11.</summary>
        /// <remarks>Read from the font's own LILY table; the ported mapping it has to
        /// agree with is EmmentalerDesignSize.Designs
        /// (scm/lily-library.scm:1702-1710 feta-design-size-mapping).</remarks>
        public double DesignSize { get; init; }

        /// <summary>The magnification this table has ALREADY been read at — 1.0 for a
        /// design's own table, magstep(font-size) for what <see cref="AtFontSize"/>
        /// hands back.</summary>
        /// <remarks>A font is a design AND a magnification, not one of the two
        /// (lily/modified-font-metric.cc:44-56 holds <c>orig_</c> and
        /// <c>magnification_</c> side by side). Boxes here are scaled already; this is
        /// for the dimensions that are NOT in this table and have to be read from the
        /// same face by hand — the glyph OUTLINE skylines
        /// (GlyphMetrics.AccidentalSkylinePair), which a caller scales itself because
        /// a skyline is mutable and every seat wants its own copy.</remarks>
        public double Magnification { get; init; } = 1.0;

        /// <summary>Whole notehead — BBox (LILC bbox).</summary>
        public BBox NoteheadWhole { get; init; }
        /// <summary>Whole notehead — the box its SKYLINE is built from (glyph outline).</summary>
        public BBox NoteheadWholeOutline { get; init; }
        /// <summary>Whole notehead — advance width (next-glyph horizontal feed).</summary>
        public double NoteheadWholeAdvance { get; init; }
        /// <summary>Half (hollow) notehead — BBox (LILC bbox).</summary>
        public BBox NoteheadHalf { get; init; }
        /// <summary>Half (hollow) notehead — the box its SKYLINE is built from (glyph outline).</summary>
        public BBox NoteheadHalfOutline { get; init; }
        /// <summary>Half (hollow) notehead — advance width (next-glyph horizontal feed).</summary>
        public double NoteheadHalfAdvance { get; init; }
        /// <summary>Black (filled) notehead — BBox (LILC bbox).</summary>
