        14 => Design14,
        16 => Design16,
        18 => Design18,
        20 => Design20,
        23 => Design23,
        26 => Design26,
        _ => throw new System.ArgumentOutOfRangeException(
            nameof(rounded), rounded, "not an Emmentaler design size"),
    };
}
